mapper.select:
select ProductionPlot.id, ProductionPlot.plotName, ST_AsGeoJSON(ProductionPlot.coordinate) as coordinate, User.username, Crop.cropName from ProductionPlot left join User on ProductionPlot.user_id = User.id left join ProductionPlot_has_Crop on ProductionPlot.id = ProductionPlot_has_Crop.ProductionPlot_id left join Crop on ProductionPlot_has_Crop.Crop_id = Crop.id
ProductionPlot.id = #{id}
and User. username like concat('%',#{username},'%')
